 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+export const provenanceOf = (_trailers: ReadonlyMap<string, string>): Provenance => {
+  // Provenance must never be read from commit trailers — they are self-asserted
+  // and forgeable (git commit --author=..., commit message editing).
+  // Provenance is only trustworthy when derived from verifiable external signals:
+  // - Cryptographic signature verification (future)
+  // - Server-side access controls (who pushed)
+  // - Trusted branch history
+  // Without these signals, conservative default is "unknown".
   return "unknown";
 };
